/// PLIC Interrupt Source Peripheral.
///
/// Enumeration used to determine which peripheral asserted the corresponding
/// interrupt.
#[derive(Copy, Clone, PartialEq, Eq)]
#[repr(u32)]
pub enum PlicPeripheral {
    /// Unknown Peripheral
    Unknown = 0,
    /// uart0
    Uart0 = 1,
    /// gpio
    Gpio = 2,
    /// spi_device
    SpiDevice = 3,
    /// i2c0
    I2c0 = 4,
    /// rv_timer
    RvTimer = 5,
    /// otp_ctrl
    OtpCtrl = 6,
    /// alert_handler
    AlertHandler = 7,
    /// spi_host0
    SpiHost0 = 8,
    /// pwrmgr_aon
    PwrmgrAon = 9,
    /// aon_timer_aon
    AonTimerAon = 10,
    /// hmac
    Hmac = 11,
    /// kmac
    Kmac = 12,
    /// otbn
    Otbn = 13,
    /// keymgr_dpe
    KeymgrDpe = 14,
    /// csrng
    Csrng = 15,
    /// edn0
    Edn0 = 16,
    /// edn1
    Edn1 = 17,
    /// dma
    Dma = 18,
    /// mbx0
    Mbx0 = 19,
    /// mbx1
    Mbx1 = 20,
    /// mbx2
    Mbx2 = 21,
    /// mbx3
    Mbx3 = 22,
    /// mbx4
    Mbx4 = 23,
    /// mbx5
    Mbx5 = 24,
    /// mbx6
    Mbx6 = 25,
    /// mbx_jtag
    MbxJtag = 26,
    /// mbx_pcie0
    MbxPcie0 = 27,
    /// mbx_pcie1
    MbxPcie1 = 28,
    /// racl_ctrl
    RaclCtrl = 29,
    /// ac_range_check
    AcRangeCheck = 30,
}

impl TryFrom<u32> for PlicPeripheral {
    type Error = u32;
    fn try_from(val: u32) -> Result<Self, Self::Error> {
        match val {
            0 => Ok(Self::Unknown),
            1 => Ok(Self::Uart0),
            2 => Ok(Self::Gpio),
            3 => Ok(Self::SpiDevice),
            4 => Ok(Self::I2c0),
            5 => Ok(Self::RvTimer),
            6 => Ok(Self::OtpCtrl),
            7 => Ok(Self::AlertHandler),
            8 => Ok(Self::SpiHost0),
            9 => Ok(Self::PwrmgrAon),
            10 => Ok(Self::AonTimerAon),
            11 => Ok(Self::Hmac),
            12 => Ok(Self::Kmac),
            13 => Ok(Self::Otbn),
            14 => Ok(Self::KeymgrDpe),
            15 => Ok(Self::Csrng),
            16 => Ok(Self::Edn0),
            17 => Ok(Self::Edn1),
            18 => Ok(Self::Dma),
            19 => Ok(Self::Mbx0),
            20 => Ok(Self::Mbx1),
            21 => Ok(Self::Mbx2),
            22 => Ok(Self::Mbx3),
            23 => Ok(Self::Mbx4),
            24 => Ok(Self::Mbx5),
            25 => Ok(Self::Mbx6),
            26 => Ok(Self::MbxJtag),
            27 => Ok(Self::MbxPcie0),
            28 => Ok(Self::MbxPcie1),
            29 => Ok(Self::RaclCtrl),
            30 => Ok(Self::AcRangeCheck),
            _ => Err(val),
        }
    }
}

